import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import type { MessageTone } from '@vybora/api';

// Bundled, original tones (generated by scripts/generate-tones.mjs).
/* eslint-disable @typescript-eslint/no-require-imports -- Metro asset modules */
const SOURCES: Record<Exclude<MessageTone, 'none'>, number> = {
  default: require('@/assets/tones/default.wav'),
  soft_chime: require('@/assets/tones/soft_chime.wav'),
  pop: require('@/assets/tones/pop.wav'),
  bell: require('@/assets/tones/bell.wav'),
  electronic: require('@/assets/tones/electronic.wav'),
};
/* eslint-enable @typescript-eslint/no-require-imports */

const players = new Map<string, AudioPlayer>();
let modeSet = false;

/** Play a message tone in-app. Respects the silent switch on iOS (does not override it). */
export async function playTone(tone: MessageTone): Promise<void> {
  if (tone === 'none') return;
  try {
    if (!modeSet) {
      await setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' });
      modeSet = true;
    }
    let player = players.get(tone);
    if (!player) {
      player = createAudioPlayer(SOURCES[tone]);
      players.set(tone, player);
    }
    await player.seekTo(0);
    player.play();
  } catch {
    // Audio is a nicety; never break messaging over it.
  }
}
